package com.dbconsole.platform.security;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class JwtTokenProvider {
    private static final Base64.Encoder BASE64_URL_ENCODER =
            Base64.getUrlEncoder().withoutPadding();
    private static final Base64.Decoder BASE64_URL_DECODER = Base64.getUrlDecoder();

    private final byte[] key;
    private final long expirationSeconds;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public JwtTokenProvider(@Value("${jwt.secret}") String secret,
                            @Value("${jwt.expiration}") long expirationSeconds) {
        this.key = sha256(secret);
        this.expirationSeconds = expirationSeconds;
    }

    public String generateToken(String username, String role) {
        long now = Instant.now().getEpochSecond();
        try {
            Map<String, Object> header = Map.of("alg", "HS256", "typ", "JWT");
            Map<String, Object> payload = new LinkedHashMap<>();
            payload.put("sub", username);
            payload.put("role", role);
            payload.put("iat", now);
            payload.put("exp", now + expirationSeconds);
            String encodedHeader = encodeJson(header);
            String encodedPayload = encodeJson(payload);
            String content = encodedHeader + "." + encodedPayload;
            return content + "." + BASE64_URL_ENCODER.encodeToString(sign(content));
        } catch (Exception ex) {
            throw new IllegalStateException("Unable to issue token", ex);
        }
    }

    public String getUsername(String token) {
        try {
            String[] parts = token.split("\\.", -1);
            if (parts.length != 3) {
                throw new IllegalArgumentException("Malformed token");
            }
            String content = parts[0] + "." + parts[1];
            byte[] suppliedSignature = BASE64_URL_DECODER.decode(parts[2]);
            if (!MessageDigest.isEqual(sign(content), suppliedSignature)) {
                throw new IllegalArgumentException("Invalid token ***");
            }
            Map<String, Object> claims = objectMapper.readValue(
                    BASE64_URL_DECODER.decode(parts[1]), new TypeReference<>() {});
            Object expiration = claims.get("exp");
            if (!(expiration instanceof Number)
                    || ((Number) expiration).longValue() <= Instant.now().getEpochSecond()) {
                throw new IllegalArgumentException("Expired token");
            }
            Object subject = claims.get("sub");
            if (!(subject instanceof String) || ((String) subject).isBlank()) {
                throw new IllegalArgumentException("Token has no subject");
            }
            return (String) subject;
        } catch (IllegalArgumentException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new IllegalArgumentException("Invalid token", ex);
        }
    }

    public boolean validateToken(String token) {
        try {
            return getUsername(token) != null;
        } catch (RuntimeException ex) {
            return false;
        }
    }

    private static byte[] sha256(String secret) {
        try {
            return MessageDigest.getInstance("SHA-256")
                    .digest(secret.getBytes(StandardCharsets.UTF_8));
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is unavailable", ex);
        }
    }

    private String encodeJson(Map<String, Object> value) throws Exception {
        return BASE64_URL_ENCODER.encodeToString(objectMapper.writeValueAsBytes(value));
    }

    private byte[] sign(String content) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(key, "HmacSHA256"));
        return mac.doFinal(content.getBytes(StandardCharsets.US_ASCII));
    }
}

package com.dbconsole.platform.service;

import com.dbconsole.platform.entity.User;
import com.dbconsole.platform.mapper.UserMapper;
import com.dbconsole.platform.security.JwtTokenProvider;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import org.springframework.stereotype.Service;

@Service
public class AuthService {
    private final UserMapper userMapper;
    private final JwtTokenProvider tokenProvider;

    public AuthService(UserMapper userMapper, JwtTokenProvider tokenProvider) {
        this.userMapper = userMapper;
        this.tokenProvider = tokenProvider;
    }

    public Optional<Map<String, String>> login(String username, String password) {
        User user = username == null ? null : userMapper.findByUsername(username);
        if (user == null || password == null || !password.equals(user.getPassword())) {
            return Optional.empty();
        }
        Map<String, String> result = new LinkedHashMap<>();
        result.put("token", tokenProvider.generateToken(user.getUsername(), user.getRole()));
        result.put("username", user.getUsername());
        result.put("role", user.getRole());
        return Optional.of(result);
    }
}

package com.dbconsole.platform.service;

import com.dbconsole.platform.dto.CreateGroupRequest;
import com.dbconsole.platform.entity.InstanceGroup;
import com.dbconsole.platform.entity.User;
import com.dbconsole.platform.mapper.InstanceGroupMapper;
import com.dbconsole.platform.mapper.InstanceMapper;
import com.dbconsole.platform.mapper.UserMapper;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.stereotype.Service;

@Service
public class GroupService {
    public enum DeleteResult { DELETED, NOT_FOUND, NOT_EMPTY }

    private final InstanceGroupMapper groupMapper;
    private final InstanceMapper instanceMapper;
    private final UserMapper userMapper;

    public GroupService(InstanceGroupMapper groupMapper, InstanceMapper instanceMapper,
                        UserMapper userMapper) {
        this.groupMapper = groupMapper;
        this.instanceMapper = instanceMapper;
        this.userMapper = userMapper;
    }

    public InstanceGroup create(CreateGroupRequest request, String username) {
        User user = requireUser(username);
        InstanceGroup group = new InstanceGroup();
        group.setName(request.getName());
        group.setDescription(request.getDescription());
        group.setOwnerId(user.getId());
        group.setCreatedAt(LocalDateTime.now());
        groupMapper.insert(group);
        return group;
    }

    public List<InstanceGroup> list(String username) {
        User user = requireUser(username);
        return isAdmin(user) ? groupMapper.findAll() : groupMapper.findByOwnerId(user.getId());
    }

    public DeleteResult delete(Long id, String username) {
        User user = requireUser(username);
        InstanceGroup group = groupMapper.findById(id);
        if (group == null || (!isAdmin(user) && !user.getId().equals(group.getOwnerId()))) {
            return DeleteResult.NOT_FOUND;
        }
        if (instanceMapper.countByGroupId(id) > 0) {
            return DeleteResult.NOT_EMPTY;
        }
        groupMapper.deleteById(id);
        return DeleteResult.DELETED;
    }

    private User requireUser(String username) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            throw new IllegalStateException("Authenticated user no longer exists");
        }
        return user;
    }

    private boolean isAdmin(User user) {
        return "ADMIN".equals(user.getRole());
    }
}

package com.dbconsole.platform.service;

import com.dbconsole.platform.dto.CreateInstanceRequest;
import com.dbconsole.platform.dto.UpdateInstanceRequest;
import com.dbconsole.platform.entity.Instance;
import com.dbconsole.platform.entity.User;
import com.dbconsole.platform.mapper.InstanceMapper;
import com.dbconsole.platform.mapper.UserMapper;
import java.net.HttpURLConnection;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.net.URL;
import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Service;

@Service
public class InstanceService {
    private static final int CONNECT_TIMEOUT_MS = 5000;

    private final InstanceMapper instanceMapper;
    private final UserMapper userMapper;

    public InstanceService(InstanceMapper instanceMapper, UserMapper userMapper) {
        this.instanceMapper = instanceMapper;
        this.userMapper = userMapper;
    }

    public Instance create(CreateInstanceRequest request, String username) {
        User user = requireUser(username);
        LocalDateTime now = LocalDateTime.now();
        Instance instance = new Instance();
        instance.setName(request.getName());
        instance.setDbType(request.getDbType());
        instance.setHost(request.getHost());
        instance.setPort(request.getPort());
        instance.setSchemaName(request.getSchemaName());
        instance.setAccount(request.getAccount());
        instance.setPassword(request.getPassword());
        instance.setGroupId(request.getGroupId());
        instance.setStatus("CREATED");
        instance.setOwnerId(user.getId());
        instance.setCreatedAt(now);
        instance.setUpdatedAt(now);
        instanceMapper.insert(instance);
        return instance;
    }

    public List<Instance> list(String dbType, Long groupId, String username) {
        User user = requireUser(username);
        return instanceMapper.findByFilters(user.getId(), dbType, groupId, isAdmin(user));
    }

    public Instance get(Long id, String username) {
        User user = requireUser(username);
        Instance instance = instanceMapper.findById(id);
        return accessible(instance, user) ? instance : null;
    }

    public Instance update(Long id, UpdateInstanceRequest request, String username) {
        Instance instance = get(id, username);
        if (instance == null) {
            return null;
        }
        if (request.getName() != null) instance.setName(request.getName());
        if (request.getHost() != null) instance.setHost(request.getHost());
        if (request.getPort() != null) instance.setPort(request.getPort());
        if (request.getSchemaName() != null) instance.setSchemaName(request.getSchemaName());
        if (request.getAccount() != null) instance.setAccount(request.getAccount());
        if (request.getPassword() != null) instance.setPassword(request.getPassword());
        if (request.getGroupId() != null) instance.setGroupId(request.getGroupId());
        instance.setUpdatedAt(LocalDateTime.now());
        instanceMapper.update(instance);
        return instanceMapper.findById(id);
    }

    public boolean delete(Long id, String username) {
        Instance instance = get(id, username);
        if (instance == null) {
            return false;
        }
        instanceMapper.deleteById(id);
        return true;
    }

    public Map<String, Object> ping(Instance instance) {
        String type = instance.getDbType();
        if ("MYSQL".equals(type) || "REDIS".equals(type)) {
            return pingTcp(instance);
        }
        if ("OSS".equals(type)) {
            return pingHttp(instance);
        }
        return pingResult(false, null, "不支持的实例类型");
    }

    private Map<String, Object> pingTcp(Instance instance) {
        if (instance.getHost() == null || instance.getPort() == null) {
            return pingResult(false, null, "主机或端口为空");
        }
        long started = System.nanoTime();
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(instance.getHost(), instance.getPort()),
                    CONNECT_TIMEOUT_MS);
            return pingResult(true, elapsedMillis(started), "连接成功");
        } catch (Exception ex) {
            return pingResult(false, null, "连接超时");
        }
    }

    private Map<String, Object> pingHttp(Instance instance) {
        if (instance.getHost() == null || instance.getHost().isBlank()) {
            return pingResult(false, null, "主机为空，未发起连接");
        }
        HttpURLConnection connection = null;
        long started = System.nanoTime();
        try {
            URL endpoint = new URL(buildEndpoint(instance.getHost(), instance.getSchemaName()));
            connection = (HttpURLConnection) endpoint.openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(CONNECT_TIMEOUT_MS);
            connection.setReadTimeout(CONNECT_TIMEOUT_MS);
            int status = connection.getResponseCode();
            return pingResult(true, elapsedMillis(started), "连接成功，状态码: " + status);
        } catch (Exception ex) {
            return pingResult(false, null, "连接超时");
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private String buildEndpoint(String host, String resource) {
        String base = host.matches("^[a-zA-Z][a-zA-Z0-9+.-]*://.*")
                ? host : "http://" + host;
        if (resource == null || resource.isEmpty()) {
            return base;
        }
        if (base.endsWith("/") && resource.startsWith("/")) {
            return base + resource.substring(1);
        }
        if (!base.endsWith("/") && !resource.startsWith("/")) {
            return base + "/" + resource;
        }
        return base + resource;
    }

    private long elapsedMillis(long started) {
        return (System.nanoTime() - started) / 1_000_000L;
    }

    private Map<String, Object> pingResult(boolean reachable, Long latencyMs, String detail) {
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("reachable", reachable);
        result.put("latencyMs", latencyMs);
        result.put("detail", detail);
        return result;
    }

    private boolean accessible(Instance instance, User user) {
        return instance != null && (isAdmin(user) || user.getId().equals(instance.getOwnerId()));
    }

    private User requireUser(String username) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            throw new IllegalStateException("Authenticated user no longer exists");
        }
        return user;
    }

    private boolean isAdmin(User user) {
        return "ADMIN".equals(user.getRole());
    }
}
